import { defineConfig } from "prisma/config";

// The database is generated by ~/dev/learning_projects/get_pokemon_api and
// copied in, so Prisma only reads its structure (`prisma db pull`). Never run
// `prisma migrate` against it: migrate would treat it as drifted and offer to
// reset it.
export default defineConfig({
  schema: "prisma/schema.prisma",
  datasource: {
    url: "file:./prisma/pokedex.db",
  },
});
